import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/transaction.dart';
import '../services/database_service.dart';
import '../services/notification_service.dart';
class AddTransactionScreen extends StatefulWidget {final DateTime month;final FinanceTransaction? item;const AddTransactionScreen({super.key,required this.month,this.item});@override State<AddTransactionScreen> createState()=>_S();}
class _S extends State<AddTransactionScreen>{final _form=GlobalKey<FormState>();late final TextEditingController _description,_value;String _category='Alimentação';bool _income=false,_paid=false,_recurring=false;late DateTime _date;final categories=['Alimentação','Dívidas','Educação','Entretenimento','Família','Habitação','Impostos','Impostos/Negócio','Lazer/Utilidades','Receita','Saúde','Serviços','Transporte','Outros'];
@override void initState(){super.initState();final x=widget.item;_description=TextEditingController(text:x?.description??'');_value=TextEditingController(text:x==null?'':x.amount.abs().toStringAsFixed(2).replaceAll('.',','));_category=x?.category??'Alimentação';_income=x?.isIncome??false;_paid=x?.paid??false;_recurring=x?.recurring??false;_date=x?.date??DateTime(widget.month.year,widget.month.month,DateTime.now().day.clamp(1,DateTime(widget.month.year,widget.month.month+1,0).day));}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.item==null?'Novo lançamento':'Editar lançamento')),body:Form(key:_form,child:ListView(padding:const EdgeInsets.all(20),children:[SegmentedButton<bool>(segments:const[ButtonSegment(value:false,label:Text('Despesa')),ButtonSegment(value:true,label:Text('Receita'))],selected:{_income},onSelectionChanged:(v)=>setState(()=>_income=v.first)),const SizedBox(height:16),TextFormField(controller:_description,decoration:const InputDecoration(labelText:'Descrição'),validator:(v)=>v==null||v.trim().isEmpty?'Informe a descrição':null),const SizedBox(height:12),TextFormField(controller:_value,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor (R\$)'),validator:(v)=>double.tryParse((v??'').replaceAll(',','.'))==null?'Valor inválido':null),const SizedBox(height:12),DropdownButtonFormField(value:_category,decoration:const InputDecoration(labelText:'Categoria'),items:categories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>_category=v!)),const SizedBox(height:12),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Vencimento / data'),subtitle:Text(DateFormat('dd/MM/yyyy').format(_date)),trailing:const Icon(Icons.calendar_month),onTap:_pickDate),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Pago / recebido'),value:_paid,onChanged:(v)=>setState(()=>_paid=v)),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Repetir todo mês'),subtitle:const Text('Cria automaticamente nos próximos meses'),value:_recurring,onChanged:(v)=>setState(()=>_recurring=v)),const SizedBox(height:18),FilledButton.icon(onPressed:_save,icon:const Icon(Icons.save),label:const Padding(padding:EdgeInsets.symmetric(vertical:14),child:Text('Salvar')))])));
Future<void> _pickDate()async{final d=await showDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(2040),initialDate:_date);if(d!=null)setState(()=>_date=d);}
Future<void> _save()async{if(!_form.currentState!.validate())return;var a=double.parse(_value.text.replaceAll(',','.')).abs();if(!_income)a=-a;final old=widget.item;final x=FinanceTransaction(id:old?.id,description:_description.text.trim(),category:_income?'Receita':_category,amount:a,date:_date,paid:_paid||_income,fortnight:_date.day<=15?1:2,recurring:_recurring,recurringDay:_recurring?_date.day:null);if(old==null){final id=await DatabaseService.instance.insert(x);await NotificationService.instance.schedule(x.copyWith(id:id));}else{await DatabaseService.instance.update(x);await NotificationService.instance.cancel(x.id!);await NotificationService.instance.schedule(x);}if(mounted)Navigator.pop(context,true);}}
